// Package secrets manages $WAF_CONFIG_DIR/secrets.env (KEY=value lines, mode 0600, git-ignored).
package secrets

import (
	"bufio"
	"bytes"
	"crypto/rand"
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"strings"
)

// Keys generated by Init.
var Keys = []string{"WAF_CH_ADMIN_PASSWORD", "WAF_CH_INGEST_PASSWORD", "WAF_CH_RO_PASSWORD"}

// Generate returns 24 random bytes, base64url without padding.
func Generate() (string, error) {
	b := make([]byte, 24)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// Init writes path with fresh values for Keys. Without force an existing file is kept,
// and only missing keys are appended. Returns the keys written.
func Init(path string, force bool) ([]string, error) {
	have := map[string]string{}
	var buf bytes.Buffer
	if !force {
		m, err := Load(path)
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			return nil, err
		}
		have = m
		if b, err := os.ReadFile(path); err == nil {
			buf.Write(b)
			if buf.Len() > 0 && !bytes.HasSuffix(b, []byte("\n")) {
				buf.WriteByte('\n')
			}
		}
	}
	if buf.Len() == 0 {
		buf.WriteString("# WAF secrets (wafctl secrets init). Never commit this file.\n")
	}
	var wrote []string
	for _, k := range Keys {
		if _, ok := have[k]; ok {
			continue
		}
		v, err := Generate()
		if err != nil {
			return nil, err
		}
		fmt.Fprintf(&buf, "%s=%s\n", k, v)
		wrote = append(wrote, k)
	}
	if len(wrote) == 0 {
		return nil, os.Chmod(path, 0o600)
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, buf.Bytes(), 0o600); err != nil {
		return nil, err
	}
	if err := os.Rename(tmp, path); err != nil {
		return nil, err
	}
	return wrote, os.Chmod(path, 0o600)
}

// Load parses KEY=value lines (# comments and blank lines ignored).
func Load(path string) (map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return map[string]string{}, err
	}
	defer f.Close()
	m := map[string]string{}
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		l := strings.TrimSpace(sc.Text())
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		k, v, ok := strings.Cut(l, "=")
		if !ok {
			continue
		}
		m[strings.TrimSpace(k)] = strings.Trim(strings.TrimSpace(v), `"'`)
	}
	return m, sc.Err()
}
